~MsgBuf();
MsgBuf(const MsgBuf& other);
MsgBuf& operator=(const MsgBuf& other);

MsgBuf::~MsgBuf()
{
    delete[] data_;
}

MsgBuf::MsgBuf(const MsgBuf& other) : len_(other.len_), data_(new char[other.len_])
{
    std::memcpy(data_, other.data_, len_);
}

MsgBuf& MsgBuf::operator=(const MsgBuf& other)
{
    if (this != &other) {
        char* p = new char[other.len_];
        std::memcpy(p, other.data_, other.len_);
        delete[] data_;
        data_ = p;
        len_ = other.len_;
    }
    return *this;
}
